-- Calculate cycle open commitments from remaining line quantities instead of stale order headers.

CREATE OR REPLACE FUNCTION public.smart_purchase_cycle_budget_guard(p_session_token text, p_branch text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp', 'extensions'
AS $function$
declare v_account record; v_today date := (now() at time zone 'Africa/Cairo')::date; v_cycle_start date; v_cycle_end date; v_prev1_start date; v_prev1_end date; v_prev2_start date; v_prev2_end date; v_cycle_days int; v_elapsed int; v_remaining_days int; v_result jsonb := '[]'::jsonb; r record;
begin
select sa.* into v_account from public.staff_sessions ss join public.staff_accounts sa on sa.id=ss.account_id where ss.token_hash=encode(extensions.digest(coalesce(p_session_token,''),'sha256'),'hex') and ss.revoked_at is null and ss.expires_at>now() and sa.status='active' order by ss.created_at desc limit 1;
if not found then return jsonb_build_object('ok',false,'error','invalid_session'); end if; if v_account.role not in ('general_manager','branch_manager','purchasing','accountant') then return jsonb_build_object('ok',false,'error','forbidden'); end if;
if extract(day from v_today) >= 26 then v_cycle_start := make_date(extract(year from v_today)::int,extract(month from v_today)::int,26); else v_cycle_start := (date_trunc('month',v_today)::date - interval '1 month')::date + 25; end if;
v_cycle_end := (v_cycle_start + interval '1 month')::date - 1; v_prev1_end := v_cycle_start - 1; v_prev1_start := (v_prev1_end - interval '1 month')::date + 1; v_prev2_end := v_prev1_start - 1; v_prev2_start := (v_prev2_end - interval '1 month')::date + 1; v_cycle_days := (v_cycle_end-v_cycle_start)+1; v_elapsed := greatest(1,(v_today-v_cycle_start)+1); v_remaining_days := greatest(0,(v_cycle_end-v_today));
for r in with branches(branch) as (select unnest(array['دواء الشامي'::text,'دواء شكري'::text])), current_spend as (select pi.branch,coalesce(sum(greatest(0,coalesce(pi.total_value,0)-coalesce(pi.returned_value,0))),0) amount from public.purchase_invoices pi where pi.invoice_date between v_cycle_start and v_today and coalesce(pi.is_sample,false)=false and pi.excluded_at is null and coalesce(pi.duplicate_review_status,'')<>'confirmed_duplicate' group by pi.branch), prev1 as (select pi.branch,coalesce(sum(greatest(0,coalesce(pi.total_value,0)-coalesce(pi.returned_value,0))),0) amount from public.purchase_invoices pi where pi.invoice_date between v_prev1_start and v_prev1_end and coalesce(pi.is_sample,false)=false and pi.excluded_at is null and coalesce(pi.duplicate_review_status,'')<>'confirmed_duplicate' group by pi.branch), prev2 as (select pi.branch,coalesce(sum(greatest(0,coalesce(pi.total_value,0)-coalesce(pi.returned_value,0))),0) amount from public.purchase_invoices pi where pi.invoice_date between v_prev2_start and v_prev2_end and coalesce(pi.is_sample,false)=false and pi.excluded_at is null and coalesce(pi.duplicate_review_status,'')<>'confirmed_duplicate' group by pi.branch), commitments as (
  select spo.branch,
         coalesce(sum(
           greatest(0,coalesce(i.approved_quantity,0)-coalesce(i.received_quantity,0))
           * greatest(0,coalesce(i.expected_unit_cost,0))
         ),0) amount
  from public.smart_purchase_orders spo
  join public.smart_purchase_order_items i on i.order_id=spo.id
  where spo.status in ('معتمدة','تم الإرسال للمورد','وصلت جزئيًا','partially_received')
  group by spo.branch
) select b.branch,coalesce(cs.amount,0)::numeric current_spend,coalesce(c.amount,0)::numeric open_commitments,coalesce(p1.amount,0)::numeric prev1_spend,coalesce(p2.amount,0)::numeric prev2_spend,s.cycle_budget configured_budget,coalesce(s.reserve_percent,20)::numeric reserve_percent,coalesce(s.reserve_days,8)::int reserve_days,coalesce(s.warning_percent,85)::numeric warning_percent from branches b left join current_spend cs on cs.branch=b.branch left join prev1 p1 on p1.branch=b.branch left join prev2 p2 on p2.branch=b.branch left join commitments c on c.branch=b.branch left join public.purchase_cycle_budget_settings s on s.branch=b.branch where (p_branch is null or p_branch='all' or b.branch=p_branch)
  and public.smart_purchase_branch_allowed_v2(v_account.id,b.branch)
loop
declare v_recommended numeric := round(greatest(0,(r.prev1_spend+r.prev2_spend)/2),2); v_budget numeric := coalesce(r.configured_budget,round(greatest(0,(r.prev1_spend+r.prev2_spend)/2),2)); v_committed numeric := r.current_spend+r.open_commitments; v_hist_daily numeric := case when (r.prev1_spend+r.prev2_spend)>0 then (r.prev1_spend+r.prev2_spend)/(2.0*v_cycle_days) else 0 end; v_forecast numeric := 0; v_paced_to_date numeric := 0; v_remaining numeric := 0; v_reserve numeric := 0; v_safe_now numeric := 0; v_daily_cap numeric := 0; v_safe_order_today numeric := 0; v_days_power numeric := 0; v_status text := 'safe'; begin if v_budget<=0 then v_budget:=greatest(r.current_spend+r.open_commitments,1); end if; v_forecast := round((r.current_spend/v_elapsed)*v_cycle_days+r.open_commitments,2); v_paced_to_date := round(v_budget*(v_elapsed::numeric/v_cycle_days),2); v_remaining := greatest(0,v_budget-v_committed); if v_remaining_days > r.reserve_days then v_reserve := greatest(v_budget*(r.reserve_percent/100.0),v_hist_daily*r.reserve_days); else v_reserve := v_hist_daily*v_remaining_days; end if; v_reserve := least(v_remaining,greatest(0,v_reserve)); v_safe_now := greatest(0,v_remaining-v_reserve); v_daily_cap := case when v_remaining_days>0 then v_remaining/(v_remaining_days+1) else v_remaining end; v_safe_order_today := least(v_safe_now,greatest(v_daily_cap,v_hist_daily)*1.25); v_days_power := case when v_hist_daily>0 then v_remaining/v_hist_daily else 0 end; if v_committed>=v_budget then v_status:='blocked'; elsif v_forecast>v_budget*1.05 then v_status:='critical'; elsif v_forecast>v_budget or v_committed>v_paced_to_date*1.05 or (v_committed/v_budget*100)>=r.warning_percent then v_status:='warning'; else v_status:='safe'; end if; v_result := v_result || jsonb_build_array(jsonb_build_object('branch',r.branch,'cycle_start',v_cycle_start,'cycle_end',v_cycle_end,'cycle_day',v_elapsed,'cycle_days',v_cycle_days,'days_remaining',v_remaining_days,'configured',r.configured_budget is not null,'cycle_budget',round(v_budget,2),'recommended_cycle_budget',v_recommended,'current_spend',round(r.current_spend,2),'open_commitments',round(r.open_commitments,2),'committed_total',round(v_committed,2),'remaining_budget',round(v_remaining,2),'paced_limit_to_date',round(v_paced_to_date,2),'pace_variance',round(v_committed-v_paced_to_date,2),'forecast_end_cycle',v_forecast,'forecast_over_budget',round(greatest(0,v_forecast-v_budget),2),'reserve_required',round(v_reserve,2),'safe_available_now',round(v_safe_now,2),'suggested_daily_cap',round(v_daily_cap,2),'safe_order_today',round(v_safe_order_today,2),'historical_daily_purchase',round(v_hist_daily,2),'days_of_purchasing_power',round(v_days_power,1),'previous_cycle_1',round(r.prev1_spend,2),'previous_cycle_2',round(r.prev2_spend,2),'usage_percent',round(v_committed/v_budget*100,1),'status',v_status,'reserve_percent',r.reserve_percent,'reserve_days',r.reserve_days,'warning_percent',r.warning_percent)); end; end loop; return jsonb_build_object('ok',true,'data',jsonb_build_object('branches',v_result,'generated_at',now())); end;$function$;
revoke all on function public.smart_purchase_cycle_budget_guard(text,text) from public;
grant execute on function public.smart_purchase_cycle_budget_guard(text,text) to anon,authenticated;
